import{_ as p,a0 as r,w as a,s as l,ao as u,I as i,x as n,a1 as o,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"Linux有问必答：如何强制在下次登录Linux时更换密码 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答：如何强制在下次登录Linux时更换密码 | LCTT (201510) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答：如何强制在下次登录Linux时更换密码 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答：如何强制在下次登录Linux时更换密码 | LCTT (201510) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201510/20151012 Linux FAQs with Answers--How to force password change at the next login on Linux","title":"Linux有问必答：如何强制在下次登录Linux时更换密码","tag":"201510","desc":""},"relativePath":"201510/20151012 Linux FAQs with Answers--How to force password change at the next login on Linux.md","filePath":"[post].md"}'),d={name:"201510/20151012 Linux FAQs with Answers--How to force password change at the next login on Linux.md"};function x(m,t,g,f,L,w){const e=r("Link");return a(),l("div",null,[t[16]||(t[16]=u(`<h1 id="linux有问必答-如何强制在下次登录linux时更换密码" tabindex="-1">Linux有问必答：如何强制在下次登录Linux时更换密码 <a class="header-anchor" href="#linux有问必答-如何强制在下次登录linux时更换密码" aria-label="Permalink to “Linux有问必答：如何强制在下次登录Linux时更换密码”">​</a></h1><blockquote><p><strong>提问</strong>：我管理着一台多人共享的Linux服务器。我刚使用默认密码创建了一个新用户，但是我想用户在第一次登录时更换密码。有没有什么方法可以让他/她在下次登录时修改密码呢？</p></blockquote><p>在多用户Linux环境中，标准实践是使用一个默认的随机密码创建一个用户账户。成功登录后，新用户自己改变默认密码。出于安全考虑，经常建议“强制”用户在第一次登录时修改密码来确保这个一次性使用的密码不会再被使用。</p><p>下面是<strong>如何强制用户在下次登录时修改他/她的密码</strong>。</p><p>每个Linux用户都关联这不同的密码相关配置和信息。比如，记录着上次密码更改的日期、最小/最大的修改密码的天数、密码何时过期等等。</p><p>一个叫chage的命令行工具可以访问并调整密码过期相关配置。你可以使用这个工具来强制用户在下次登录修改密码、</p><p>要查看特定用户的过期信息（比如：alice），运行下面的命令。注意的是除了你自己之外查看其他任何用户的密码信息都需要root权限。</p><pre><code>$ sudo chage -l alice 
</code></pre><p><img src="https://c1.staticflickr.com/1/727/21955581605_5471e61ee0_c.jpg" alt=""></p><h3 id="强制用户修改密码" tabindex="-1">强制用户修改密码 <a class="header-anchor" href="#强制用户修改密码" aria-label="Permalink to “强制用户修改密码”">​</a></h3><p>如果你想要强制用户去修改他/她的密码,使用下面的命令。</p><pre><code>$ sudo chage -d0 &lt;user-name&gt; 
</code></pre><p>原本<code>-d &lt;N&gt;</code>参数是用来设置密码的“年龄”（也就是上次修改密码起到1970/1/1起的天数）。因此“-d0”的意思是上次密码修改的时间是1970/1/1，这就让当前的密码过期了，也就强制让他在下次登录的时候修改密码了。</p><p>另外一个过期当前密码的方式是用passwd命令。</p><pre><code>$ sudo passwd -e &lt;user-name&gt; 
</code></pre><p>上面的命令和“chage -d0”作用一样，让当前用户的密码立即过期。</p><p>现在检查用户的信息，你会发现：</p><p><img src="https://c2.staticflickr.com/6/5770/21767501480_ba88f00d80_c.jpg" alt=""></p><p>当你再次登录时候，你会被要求修改密码。你会在修改前被要求再验证一次当前密码。</p><p><img src="https://c2.staticflickr.com/6/5835/21929638636_eed4d69cb9_c.jpg" alt=""></p>`,20)),i("p",null,[t[1]||(t[1]=n("要设置更全面的密码策略（如密码复杂性，防止重复使用），则可以使用PAM。参见",-1)),o(e,{href:"http://xmodulo.com/set-password-policy-linux.html"},{default:s(()=>[...t[0]||(t[0]=[n("这篇文章",-1)])]),_:1}),t[2]||(t[2]=n("了解更多详情。",-1))]),t[17]||(t[17]=i("hr",null,null,-1)),i("p",null,[t[4]||(t[4]=n("via: ",-1)),o(e,{href:"http://ask.xmodulo.com/force-password-change-next-login-linux.html"},{default:s(()=>[...t[3]||(t[3]=[n("http://ask.xmodulo.com/force-password-change-next-login-linux.html",-1)])]),_:1})]),i("p",null,[t[8]||(t[8]=n("作者：",-1)),o(e,{href:"http://ask.xmodulo.com/author/nanni"},{default:s(()=>[...t[5]||(t[5]=[n("Dan Nanni",-1)])]),_:1}),t[9]||(t[9]=n(" 译者：",-1)),o(e,{href:"https://github.com/geekpi"},{default:s(()=>[...t[6]||(t[6]=[n("geekpi",-1)])]),_:1}),t[10]||(t[10]=n(" 校对：",-1)),o(e,{href:"https://github.com/wxy"},{default:s(()=>[...t[7]||(t[7]=[n("wxy",-1)])]),_:1})]),i("p",null,[t[13]||(t[13]=n("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[11]||(t[11]=[n("LCTT",-1)])]),_:1}),t[14]||(t[14]=n(" 原创编译，",-1)),o(e,{href:"https://linux.cn/"},{default:s(()=>[...t[12]||(t[12]=[n("Linux中国",-1)])]),_:1}),t[15]||(t[15]=n(" 荣誉推出",-1))])])}const k=p(d,[["render",x]]);export{_ as __pageData,k as default};
